// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        // Restrict to addresses that are likely to have code deployed,
        // but keep the domain wide so the fuzzer can still trigger the bug.
        vm.assume(caddress.code.length > 0);
        // Ensure `from` is not zero if the external call checks for it.
        vm.assume(from != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // The reference C encodes as transferFrom(address,address,uint256) and succeeds
        // when called on any contract that does not revert on unrecognized selectors (fallback).
        // Since we assume `caddress` is a contract with code, a mismatched selector
        // (transfer(address,uint256)) used by the mutant will likely cause a revert,
        // while the correct one will not.
        bool ok = c.transfer(from, caddress, _tos, v);
        assertTrue(ok);
    }
}

